   507    public:
   508    struct accelerator_t
   509    {
   510      void init (hb_face_t *face)
   511      {
   512        gvar_table = hb_sanitize_context_t ().reference_table<gvar> (face);
   513        hb_blob_ptr_t<fvar> fvar_table = hb_sanitize_context_t ().reference_table<fvar> (face);
   514        unsigned int axis_count = fvar_table->get_axis_count ();
   515        fvar_table.destroy ();
   516
   517        if (unlikely ((gvar_table->glyphCount != face->get_num_glyphs ()) ||
   518                      (gvar_table->axisCount != axis_count)))
   519          fini ();
   520
   521        unsigned int num_shared_coord = gvar_table->sharedTupleCount * gvar_table->axisCount;
   522        shared_tuples.resize (num_shared_coord);
   523        for (unsigned int i = 0; i < num_shared_coord; i++)
   524          shared_tuples[i] = (&(gvar_table + gvar_table->sharedTuples))[i];
   525      }
   526
   527      void fini ()
   528      {
   529        gvar_table.destroy ();
   530        shared_tuples.fini ();
   531      }
   532
   533      private:
   534      struct x_getter { static float get (const contour_point_t &p) { return p.x; } };
   535      struct y_getter { static float get (const contour_point_t &p) { return p.y; } };
   536
   537      template <typename T>
   538      static float infer_delta (const hb_array_t<contour_point_t> points,
   539                                const hb_array_t<contour_point_t> deltas,
   540                                unsigned int target, unsigned int prev, unsigned int next)
   541      {
   542        float target_val = T::get (points[target]);
   543        float prev_val = T::get (points[prev]);
   544        float next_val = T::get (points[next]);
   545        float prev_delta = T::get (deltas[prev]);
   546        float next_delta = T::get (deltas[next]);
   547
   548        if (prev_val == next_val)
   549          return (prev_delta == next_delta) ? prev_delta : 0.f;
   550        else if (target_val <= hb_min (prev_val, next_val))
   551          return (prev_val < next_val) ? prev_delta : next_delta;
   552        else if (target_val >= hb_max (prev_val, next_val))
   553          return (prev_val > next_val) ? prev_delta : next_delta;
   554
   555        /* linear interpolation */
   556        float r = (target_val - prev_val) / (next_val - prev_val);
   557        return (1.f - r) * prev_delta + r * next_delta;
   558      }
   559
   560      static unsigned int next_index (unsigned int i, unsigned int start, unsigned int end)
   561      { return (i >= end) ? start : (i + 1); }
   562
   563      public:
   564      bool apply_deltas_to_points (hb_codepoint_t glyph,
   565                                   const int *coords, unsigned int coord_count,
   566                                   const hb_array_t<contour_point_t> points) const
   567      {
   568        coord_count = hb_min (coord_count, gvar_table->axisCount);
   569        if (!coord_count || coord_count != gvar_table->axisCount) return true;
   570
   571        const GlyphVarData &var_data = gvar_table->get_glyph_var_data (glyph);
   572        if (!var_data.has_data ()) return true;
   573        hb_vector_t<unsigned int> shared_indices;
   574        GlyphVarData::tuple_iterator_t iterator;
   575        if (!GlyphVarData::get_tuple_iterator (&var_data,
   576                                               gvar_table->get_glyph_var_data_length (glyph),
   577                                               gvar_table->axisCount,
   578                                               shared_indices,
   579                                               &iterator))
   580          return true; /* so isn't applied at all */
   581
   582        /* Save original points for inferred delta calculation */
   583        contour_point_vector_t orig_points;
   584        orig_points.resize (points.length);
   585        for (unsigned int i = 0; i < orig_points.length; i++)
   586          orig_points[i] = points[i];
   587
   588        contour_point_vector_t deltas; /* flag is used to indicate referenced point */
   589        deltas.resize (points.length);
   590
   591        do
   592        {
   593          float scalar = iterator.current_tuple->calculate_scalar (coords, coord_count, shared_tuples.as_array ());
   594          if (scalar == 0.f) continue;
   595          const HBUINT8 *p = iterator.get_serialized_data ();
   596          unsigned int length = iterator.current_tuple->get_data_size ();
   597          if (unlikely (!iterator.in_range (p, length)))
   598            return false;
   599
   600          hb_bytes_t bytes ((const char *) p, length);
   601          hb_vector_t<unsigned int> private_indices;
   602          if (iterator.current_tuple->has_private_points () &&
   603              !GlyphVarData::unpack_points (p, private_indices, bytes))
   604            return false;
   605          const hb_array_t<unsigned int> &indices = private_indices.length ? private_indices : shared_indices;
   606
   607          bool apply_to_all = (indices.length == 0);
   608          unsigned int num_deltas = apply_to_all ? points.length : indices.length;
   609          hb_vector_t<int> x_deltas;
   610          x_deltas.resize (num_deltas);
   611          if (!GlyphVarData::unpack_deltas (p, x_deltas, bytes))
   612            return false;
   613          hb_vector_t<int> y_deltas;
   614          y_deltas.resize (num_deltas);
   615          if (!GlyphVarData::unpack_deltas (p, y_deltas, bytes))
   616            return false;
   617
   618          for (unsigned int i = 0; i < deltas.length; i++)
   619            deltas[i].init ();
   620          for (unsigned int i = 0; i < num_deltas; i++)
   621          {
   622            unsigned int pt_index = apply_to_all ? i : indices[i];
   623            deltas[pt_index].flag = 1;    /* this point is referenced, i.e., explicit deltas specified */
   624            deltas[pt_index].x += x_deltas[i] * scalar;
   625            deltas[pt_index].y += y_deltas[i] * scalar;
   626          }
   627
   628          /* find point before phantoms start which is an end point */
   629          unsigned all_contours_end = points.length ? points.length - 1 : 0;
   630          while (all_contours_end > 0)
   631          {
   632            if (points[all_contours_end].is_end_point) break;
   633            --all_contours_end;
   634          }
   635
   636          /* infer deltas for unreferenced points */
   637          for (unsigned start_point = 0; start_point < all_contours_end; ++start_point)
   638          {
   639            /* Check the number of unreferenced points in a contour. If no unref points or no ref points, nothing to do. */
   640            unsigned end_point = start_point;
   641            unsigned unref_count = 0;
   642            for (; end_point <= all_contours_end; ++end_point)
   643            {
   644              if (!deltas[end_point].flag)
   645                unref_count++;
   646              if (points[end_point].is_end_point)
   647                break;
   648            }
   649
   650            unsigned j = start_point;
   651            if (unref_count == 0 || unref_count > end_point - start_point)
   652              goto no_more_gaps;
   653
   654            for (;;)
   655            {
   656              /* Locate the next gap of unreferenced points between two referenced points prev and next.
   657               * Note that a gap may wrap around at left (start_point) and/or at right (end_point).
   658               */
   659              unsigned int prev, next, i;
   660              for (;;)
   661              {
   662                i = j;
   663                j = next_index (i, start_point, end_point);
   664                if (deltas[i].flag && !deltas[j].flag) break;
   665              }
   666              prev = j = i;
   667              for (;;)
   668              {
   669                i = j;
   670                j = next_index (i, start_point, end_point);
   671                if (!deltas[i].flag && deltas[j].flag) break;
   672              }
   673              next = j;
   674              /* Infer deltas for all unref points in the gap between prev and next */
   675              i = prev;
   676              for (;;)
   677              {
   678                i = next_index (i, start_point, end_point);
   679                if (i == next) break;
   680                deltas[i].x = infer_delta<x_getter> (orig_points.as_array (), deltas.as_array (), i, prev, next);
   681                deltas[i].y = infer_delta<y_getter> (orig_points.as_array (), deltas.as_array (), i, prev, next);
   682                if (--unref_count == 0) goto no_more_gaps;
   683              }
   684            }
   685  no_more_gaps:
   686            start_point = end_point + 1;
   687          }
   688
   689          /* apply specified / inferred deltas to points */
   690          for (unsigned int i = 0; i < points.length; i++)
   691          {
   692            points[i].x += (float) roundf (deltas[i].x);
   693            points[i].y += (float) roundf (deltas[i].y);
   694          }
   695        } while (iterator.move_to_next ());
   696
   697        return true;
   698      }
